import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const sessionCookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie" && /^session=/.test(h.value));
  expect(sessionCookies, JSON.stringify(response.headersArray())).toHaveLength(1);
  const cookie = sessionCookies[0].value;
  // A cleared cookie has an empty value and expires immediately.
  expect(cookie, cookie).toMatch(/^session=(""|);/);
  expect(cookie.toLowerCase(), cookie).toContain("max-age=0");
});
